const key='weyra:local-wardrobe:v2';
export const picture=(item:Garment):ImageSourcePropType=>item.imageUrl?{uri:item.imageUrl}:item.source!;
const listeners=new Set<()=>void>();
export const notifyCloset=()=>listeners.forEach(fn=>fn());
export async function saveLocalGarments(items:Garment[]){await AsyncStorage.setItem(key,JSON.stringify(items));listeners.forEach(notify=>notify());}
export function useCloset(){
 const {session}=useAuth();const [revision,setRevision]=useState(0);useEffect(()=>{const notify=()=>setRevision(v=>v+1);listeners.add(notify);return()=>{listeners.delete(notify);};},[]);const [items,setItems]=useState<Garment[]>([]);const [ready,setReady]=useState(false);const [error,setError]=useState('');
 useEffect(()=>{let live=true;(async()=>{try{
 if(isSupabaseConfigured){if(!session){if(live)setItems([]);return;}const q=await supabase.from('wardrobe_items').select('id,name,category,colors,image_path,cutout_image_path,wear_count').order('created_at',{ascending:false});if(q.error)throw q.error;const hydrated=await Promise.all((q.data??[]).map(async p=>{const u=await supabase.storage.from('user-photos').createSignedUrl(p.cutout_image_path??p.image_path,3600);return {...p,name:p.name??'',imageUrl:u.data?.signedUrl};}));if(live)setItems(hydrated);
 }else{const raw=await AsyncStorage.getItem(key);const local=raw?JSON.parse(raw):[];if(!Array.isArray(local))throw new Error('Invalid wardrobe data');if(live)setItems([...local,...sampleGarments]);}
 }catch(e){if(live&&!isSupabaseConfigured)setItems(sampleGarments);if(live)setError(e instanceof Error?e.message:String(e));}finally{if(live)setReady(true);}})();return()=>{live=false;};},[session,revision]);
 async function add(item:Garment){const local=[item,...items.filter(p=>!p.id.startsWith('photo-'))];await saveLocalGarments(local);setItems([...local,...sampleGarments]);}
 async function addMany(added:Garment[]){if(isSupabaseConfigured)throw new Error('localOnly');if(added.some(p=>!p.name.trim()||!p.colors.length))throw new Error('reviewRequired');const local=[...added,...items.filter(p=>!p.id.startsWith('photo-'))];await saveLocalGarments(local);setItems([...local,...sampleGarments]);}
 async function update(item:Garment){if(isSupabaseConfigured||!item.id.startsWith('local-'))throw new Error('localOnly');const local=items.filter(p=>!p.id.startsWith('photo-')).map(p=>p.id===item.id?item:p);await saveLocalGarments(local);setItems([...local,...sampleGarments]);}
 async function remove(id:string){const next=items.filter(p=>p.id!==id);await saveLocalGarments(next.filter(p=>!p.id.startsWith('photo-')));setItems(next);}
 return{items,ready,error,add,addMany,remove,update};
}
